import re
import os
import subprocess
import time
from robot.api import logger
from datetime import datetime
import threading

DEFAULT_PORT = '7070'
DL_NAT_GW = UL_NAT_GW = '10.0.2.1'
UPF_IP = '1.2.4.1'
DEFAULT_PACKET_SIZE = '700'


class ThroughputException(Exception):
    pass


class IperfServer(object):
    def __init__(self):
        self.iperf_server = None
        self.iperf_client = None

    def start(self, server, port, client, throughput, duration, packet_size):
        iperf_server_cmd = ['iperf', '-s', '-u', '-B', server, '-p', port, '-i', '1']
        iperf_client_cmd = \
            ['iperf', '-c', client, '-u', '-b', throughput, '-p', port, '-l', packet_size, '-t', duration]
        logger.info("Start iperf server by executing '{}'".format(" ".join(iperf_server_cmd)), also_console=True)
        self.iperf_server = subprocess.Popen(iperf_server_cmd, stdout=subprocess.PIPE, universal_newlines=True)
        logger.info("Start iperf traffic by executing '{}'".format(" ".join(iperf_client_cmd)), also_console=True)
        self.iperf_client = subprocess.Popen(iperf_client_cmd)
        time.sleep(1)
        return self.iperf_server, self.iperf_client

    def start_server_and_save_output(self, server, port, interval, l4s, file_path):
        iperf_cmd = 'iperf'
        if l4s:
            iperf_cmd = 'iperf-l4s -u -e'
        iperf_server_cmd = "{} -s -p {} -i {} -B {} | tee {}".format(iperf_cmd, port, interval, server, file_path)
        logger.info("Start iperf server by executing '{}'".format(iperf_server_cmd), also_console=True)
        self.iperf_server = subprocess.Popen(iperf_server_cmd, shell=True, stdout=subprocess.PIPE, universal_newlines=True)
        time.sleep(0.2)
        return self.iperf_server

    def start_client_and_save_output(self, server, port, client, throughput, duration, interval, packet_size, l4s, file_path):
        iperf_cmd = 'iperf --trip-times'
        if l4s:
            iperf_cmd = 'iperf-l4s -u -e --udp-l4s --trip-times'
        iperf_client_cmd = "{} -c {} -p {} -l {} -t {} -i {} -B {} -b {} | tee {}".format(iperf_cmd, client, port, packet_size, duration,
                                                                                          interval, server, throughput, file_path)
        logger.info("Start iperf server by executing '{}'".format(iperf_client_cmd), also_console=True)
        self.iperf_client = subprocess.Popen(iperf_client_cmd, shell=True, stdout=subprocess.PIPE, universal_newlines=True)
        return self.iperf_client


class ta5g_iperf_traffic(object):
    def __init__(self):
        self.iperf_server_downlink = None
        self.iperf_client_downlink = None
        self.iperf_server_uplink = None
        self.iperf_client_uplink = None
        self.iperf_server = None
        self.iperf_client = None
        self.egate_console_log_path = "/opt/iphy/latest/egate_console.log"
        self.uec_log_path = "/opt/iphy/latest/uec_1.log"

    def start_downlink_and_uplink_traffic(
        self,
        downlink_tput='1m',
        uplink_tput='1m',
        duration='60s',
        downlink_pdu_gw_id=1,
        dl_nat_gw=DL_NAT_GW,
        port=DEFAULT_PORT,
        uplink_pdu_gw_id=1,
        ul_nat_gw=UL_NAT_GW,
        packet_size=DEFAULT_PACKET_SIZE,
        check_if_tput_started=True,
        ue_ip=None
    ):
        """
        downlink_tput: str, optional. Desired throughput for the downlink traffic. Default is '1m' (1 Mbps).
        uplink_tput: str, optional. Desired throughput for the uplink traffic. Default is '1m' (1 Mbps).
        duration: str, optional. Duration for which the traffic should be generated. Default is '60s' (60 seconds).
        downlink_pdu_gw_id: int, optional. Gateway value for downlink from egate command 'ue_pdu_session_setup ue=n pdu=n gw=n' or gw_id from
        robot keyword 'Establish Pdu Session    ue_id=n    pdu_id=n    gw_id=n'. Default is 1.
        dl_nat_gw: str. Downlink NAT gateway from the PDU session.
        port: int, optional. Port number to be used for the traffic. Default is DEFAULT_PORT.
        uplink_pdu_gw_id: int, optional. Gateway value for uplink from egate command 'ue_pdu_session_setup ue=n pdu=n gw=n' or gw_id from
        robot keyword 'Establish Pdu Session    ue_id=n    pdu_id=n    gw_id=n'. Default is 1.
        ul_nat_gw: str. Uplink NAT gateway from the PDU session.
        packet_size: int, optional. Size of the packets to be used in the traffic. Default is DEFAULT_PACKET_SIZE.
        check_if_tput_started: bool, optional. Flag to check if the throughput has started. Default is True.
        ue_ip: str, optional. IP address of the User Equipment (UE). If None, it will be set to ue_pdu_ip. Default is None.
        """
        self.start_downlink_traffic(
            pdu_gw_id=downlink_pdu_gw_id,
            throughput=downlink_tput,
            duration=duration,
            dl_nat_gw=dl_nat_gw,
            port=port,
            packet_size=packet_size,
            check_if_tput_started=check_if_tput_started,
            ue_ip=ue_ip
        )
        self.start_uplink_traffic(
            pdu_gw_id=uplink_pdu_gw_id,
            throughput=uplink_tput,
            duration=duration,
            ul_nat_gw=ul_nat_gw,
            port=port,
            direction='both',
            packet_size=packet_size,
            check_if_tput_started=check_if_tput_started,
            ue_ip=ue_ip
        )

    def start_downlink_traffic(
        self,
        pdu_gw_id=1,
        throughput='1m',
        duration='60s',
        direction='single',
        dl_nat_gw=DL_NAT_GW,
        port=DEFAULT_PORT,
        packet_size=DEFAULT_PACKET_SIZE,
        check_if_tput_started=True,
        ue_ip=None
    ):
        """
        pdu_gw_id: int, optional. Gateway value from egate command 'ue_pdu_session_setup ue=n pdu=n gw=n' or gw_id from robot keyword
        'Establish Pdu Session    ue_id=n    pdu_id=n    gw_id=n'. Default is 1.
        throughput: str, optional. Desired throughput for the downlink traffic. Default is '1m' (1 Mbps).
        duration: str, optional. Duration for which the traffic should be generated. Default is '60s' (60 seconds).
        direction: str, optional. Direction of the traffic. Can be 'single' or 'both'. Default is 'single'.
        dl_nat_gw: str. Downlink NAT gateway from the PDU session.
        port: int, optional. Port number to be used for the traffic. Default is DEFAULT_PORT.
        packet_size: int, optional. Size of the packets to be used in the traffic. Default is DEFAULT_PACKET_SIZE.
        check_if_tput_started: bool, optional. Flag to check if the throughput has started. Default is True.
        ue_ip: str, optional. IP address of the User Equipment (UE). If None, it will be set to ue_pdu_ip. Default is None.
        """
        if not ue_ip:
            ue_ip = self._get_ue_pdu_ip(gw_id=pdu_gw_id)
        self.iperf_server_downlink, self.iperf_client_downlink = IperfServer().start(
            server=dl_nat_gw, port=port, client=ue_ip, throughput=throughput, duration=duration, packet_size=packet_size
        )
        if check_if_tput_started:
            self.check_if_tput_started(
                throughput=throughput,
                iperf_server=self.iperf_server_downlink,
                close_if_tput_not_found=self.stop_downlink_traffic,
                direction=direction,
            )

    def start_uplink_traffic(
        self,
        pdu_gw_id=1,
        throughput='1m',
        duration='60s',
        direction='single',
        ul_nat_gw=UL_NAT_GW,
        port=DEFAULT_PORT,
        packet_size=DEFAULT_PACKET_SIZE,
        check_if_tput_started=True,
        ue_ip=None
    ):
        """
        pdu_gw_id: int, optional. Gateway value from egate command 'ue_pdu_session_setup ue=n pdu=n gw=n' or gw_id from robot keyword
        'Establish Pdu Session    ue_id=n    pdu_id=n    gw_id=n'. Default is 1.
        throughput: str, optional. Desired throughput for the uplink traffic. Default is '1m' (1 Mbps).
        duration: str, optional. Duration for which the traffic should be generated. Default is '60s' (60 seconds).
        direction: str, optional. Direction of the traffic. Can be 'single' or 'both'. Default is 'single'.
        ul_nat_gw: str. Uplink NAT gateway from the PDU session.
        port: int, optional. Port number to be used for the traffic. Default is DEFAULT_PORT.
        packet_size: int, optional. Size of the packets to be used in the traffic. Default is DEFAULT_PACKET_SIZE.
        check_if_tput_started: bool, optional. Flag to check if the throughput has started. Default is True.
        ue_ip: str, optional. IP address of the User Equipment (UE). If None, it will be set to ue_pdu_ip. Default is None.
        """
        if not ue_ip:
            ue_ip = self._get_ue_pdu_ip(gw_id=pdu_gw_id)
        self.iperf_server_uplink, self.iperf_client_uplink = IperfServer().start(
            server=ul_nat_gw, port=port, client=ue_ip, throughput=throughput, duration=duration, packet_size=packet_size
        )
        if check_if_tput_started:
            self.check_if_tput_started(
                throughput=throughput,
                iperf_server=self.iperf_server_uplink,
                close_if_tput_not_found=self.stop_uplink_traffic,
                direction=direction,
            )

    def start_server_and_save_output(
        self,
        file_path,
        server=UL_NAT_GW,
        port=DEFAULT_PORT,
        interval=30,
        l4s=False
    ):
        """
        Starts an iPerf server and saves the output to a specified file.

        :param file_path: str. The path to the file where the output should be saved.
        :param server: str, optional. Server IP. Default is UL_NAT_GW.
        :param port: int, optional. Port number to be used for the server. Default is DEFAULT_PORT.
        :param interval: int, optional. Interval in seconds between periodic bandwidth reports. Default is 30 seconds.
        :param l4s: bool, optional. Flag to enable Low Latency Low Loss Scalable Throughput (L4S) support. Default is False.
        """
        self.iperf_server = IperfServer().start_server_and_save_output(
            server=server, port=port, interval=interval, l4s=l4s, file_path=file_path
        )

    def start_client_and_save_output(
        self,
        file_path,
        ue_ip,
        throughput='1m',
        duration='60',
        interval='30',
        server=UL_NAT_GW,
        port=DEFAULT_PORT,
        packet_size=DEFAULT_PACKET_SIZE,
        l4s=False
    ):
        """
        Starts an iPerf client and saves the output to a specified file.

        :param file_path: str. The path to the file where the output should be saved.
        :param ue_ip: str. IP address of the User Equipment (UE).
        :param throughput: str, optional. Desired throughput for the uplink traffic. Default is '1m' (1 Mbps).
        :param duration: str, optional. Duration for which the traffic should be generated. Default is '60' (60 seconds).
        :param interval:
        :param server: str, optional. Server IP. Default is UL_NAT_GW.
        :param port: int, optional. Port number to be used for the client. Default is DEFAULT_PORT.
        :param packet_size: int, optional. Size of the packets to be used in the traffic. Default is DEFAULT_PACKET_SIZE.
        :param l4s: bool, optional. Flag to enable Low Latency Low Loss Scalable Throughput (L4S) support. Default is False.
        """
        self.iperf_server = IperfServer().start_client_and_save_output(
            server=server, port=port, client=ue_ip, throughput=throughput,
            duration=duration, interval=interval, packet_size=packet_size, l4s=l4s, file_path=file_path
        )

    def stop_downlink_traffic(self):
        self.iperf_client_downlink.kill()
        self.iperf_server_downlink.kill()

    def stop_uplink_traffic(self):
        self.iperf_client_uplink.kill()
        self.iperf_server_uplink.kill()

    def stop_all_traffics(self):
        os.system("ps -ef | grep iperf | awk '{print $2}' | xargs kill -9 $1 >/dev/null 2>&1")

    @staticmethod
    def _expected_throughput_reached(throughput, expected, margin='10%'):
        margin = float(margin.replace('%', '')) * 0.01
        margin *= throughput
        expected = float(re.match(r'\s*(\d+).*', expected).group(1))
        if throughput + margin > float(expected):
            return True

    def _check_if_tput_is_reached(self, expected_throughput, iperf_server):
        tput = 0
        is_tput_reached = False
        t1 = datetime.now()
        no_tput_timeout = 11
        timer = threading.Timer(no_tput_timeout, iperf_server.terminate)
        timer.start()
        while (datetime.now() - t1).seconds <= 10:
            try:
                nextline = iperf_server.stdout.readline()
                logger.info(nextline)
                tput = float(re.search(r'(\d+\.\d+)\s+Mbits/sec', nextline).group(1))
            except Exception:
                pass
            is_tput_reached = self._expected_throughput_reached(tput, expected_throughput)
            if is_tput_reached:
                logger.console('Tput started correctly, continuing')
                break
        return is_tput_reached, tput

    def check_if_tput_started(self, throughput, iperf_server, close_if_tput_not_found, direction):
        is_tput_reached, found_tput = self._check_if_tput_is_reached(throughput, iperf_server)
        if not is_tput_reached:
            close_if_tput_not_found() if direction == 'single' else self.stop_all_traffics()
            raise ThroughputException(
                '10 seconds timeout expired, Throughput {} is lower than expected {}'.format(found_tput, throughput)
            )

    def start_traffic_and_check_if_average_throughput_is_reached(
        self, pdu_gw_id, throughput='1m', duration='60s', direction='dl', margin='2%'
    ):
        if direction == 'ul':
            self.start_uplink_traffic(pdu_gw_id=pdu_gw_id, throughput=throughput, duration=duration)
        else:
            self.start_downlink_traffic(pdu_gw_id=pdu_gw_id, throughput=throughput, duration=duration)
        throughput_list = []
        start_time = time.time()
        while time.time() < start_time + float(re.sub(r'\D', '', duration)) - 10:
            if direction == 'ul':
                is_tput_reached, found_tput = self._check_if_tput_is_reached(throughput, self.iperf_server_uplink)
            else:
                is_tput_reached, found_tput = self._check_if_tput_is_reached(throughput, self.iperf_server_downlink)
            throughput_list.append(found_tput)
            logger.info("tput: {}".format(found_tput), also_console=True)
        average_throughput = sum(throughput_list) / len(throughput_list)
        if average_throughput < float(re.sub(r'\D', '', throughput)) * (1 - float(re.sub(r'\D', '', margin)) / 100):
            raise ThroughputException(
                '{} timeout expired, Throughput {} is lower than expected {}'.format(
                    duration, average_throughput, float(re.sub(r'\D', '', throughput))
                )
            )
        else:
            logger.info(
                'Average {} throughput {} reaches expected {} with {} margin'.format(
                    direction, average_throughput, throughput, margin
                ),
                also_console=True,
            )

    def _get_gw_ip(self, gw_id):
        regexp = re.compile(r'(?<=ue_nat_ip=)([^\s]+)')
        with open(self.egate_console_log_path, "r") as egate_console:
            for line in egate_console:
                if "set_pdu_gateway" in line and "id={}".format(gw_id) in line:
                    return regexp.search(line).group()
        raise LookupError("There is no line containing 'set_pdu_gateway' and 'id={0}' in egate_console.log; "
                          "There are at least two possible causes: \n"
                          "    1. Pdu session with pdu gateway id={0} is not configured,"
                          " if it is true configure it in egate configuration file,\n"
                          "    2. You are not using Reach Onair keyword from ta5g_egate, which may result "
                          "in wrong logging settings in egate configuration file. Please use "
                          "Reach Onair or add manually following command at the beginning of egate config file:\n"
                          "    exec('set_log log_to_file=on') - in case of .lua syntax,\n"
                          "    set_log log_to_file=on - in case of .cfg syntax.\n"
                          "If none of these solutions helped please contact I_TA5G_SUPPORT.".format(gw_id))

    def _get_ue_pdu_ip(self, gw_id):
        regexp = re.compile(r'(?<=ue_nat_ip=)([^\s]+)')
        with open(self.egate_console_log_path, "r") as egate:
            for line in egate:
                if "set_pdu_gateway" in line:
                    if "id={}".format(gw_id) in line:
                        return regexp.search(line).group().split("ue_nat_ip=")[0]
        raise LookupError('There is no UE Ip corresponding to pdu gateway defined with id={}'.format(gw_id))
